# forward_blocking_jatos.R
#
# Import, validate and save data sets generated by new studies conducted within
# the CATLAS project via JATOS.
#
# NOTE:
# In CATLAS, the experimental data are save to JATOS server trial-by-trial.
# This results in raw JATOS that have few perks, notably they have "json-like"
# structure with missing square brackets ("[]") around the data and missing
# commas between curly brackets ("{}") delineating data components. This script
# introduces a `raw2json()` function later coupled with {jsonlite} import to
# deal with this issue.

#library(catlasr)
library(tidyverse)
library(jatosR)
library(jsonlite)

# Make sure you have a valid JATOS API token before starting.
# If not, visit https://github.com/visionlabels/jatosR.git for instructions.


# --- 0. Set-up ----------------------------------------------
url <- "https://jatos.mindprobe.eu"
tok <- Sys.getenv("mindprobe_catlas_token") # Saved via usethis::edit_r_environ()
bid <- c(28758)

.meta_cols <- c(
  "id", "email", "sex", "age",
  "width", "height", "browser", "browser_version", "mobile", "os", "vsync_rate"
)

.resp_cols <- c(
  "id",
  "stage", "block", "type",
  "cues", "response", "confidence", "rt1", "rt2",
  "correct_outcome", "is_correct", "timed_out"
)

.cues_map <- list(
  A  = "A",           AB = c("AB", "BA"),
  BK = c("BK", "KB"), BN = c("BN", "NB"), BT = c("BT", "TB"),
  C  = "C",           CD = c("CD", "DC"),
  DK = c("DK", "KD"), DN = c("DN", "ND"), DQ = c("DQ", "QD"),
  E  = "E",           EF = c("EF", "FE"),
  FN = c("FN", "NF"), FQ = c("FQ", "QF"), FT = c("FT", "TF"),
  G  = "G",           GH = c("GH", "HG"),
  HK = c("HK", "KH"), HQ = c("HQ", "QH"), HT = c("HT", "TH"),
  I  = "I",           JK = c("JK", "KJ"),
  L  = "L",           MN = c("MN", "NM"),
  O  = "O",           PQ = c("PQ", "QP"),
  R  = "R",           ST = c("ST", "TS"),
  UV = c("UV", "VU"),
  WX = c("WX", "XW"),
  YZ = c("YZ", "ZY"),
  alphabeta = c("alphabeta", "betaalpha")
)


raw2json <- function(x) {
  output <- gsub("}{", "},{", x, fixed = TRUE)
  paste0("[", output, "]")
}


# --- 1. Download data from JATOS ----------------------------------------------
cc <- define_connection(url, tok)

test <- try(test_connection(cc), silent = TRUE)
if (inherits(test, "try-error")) {
  cli::cli_abort(c(
    "x" = "Connection test failed.",
    "i" = "Did you forget to specify a valid token?",
    "i" = "See https://github.com/visionlabels/jatosR.git"
  ))
}

jatos_data <-
  map_dfr(bid, function(batch) {
    meta <- get_metadata(jc = cc, batch_id = batch)
    results <- get_results (jc = cc, batch_id = batch)
    process_results(meta, results)$data
  })


# --- 2. Extract jsPsych data --------------------------------------------------
jspsych_data_all <-
  jatos_data |>
  mutate(data_jspsych = map2(data_raw, id_sr, function(d, i) {
    data <- d |>
      raw2json() |>
      fromJSON() |>
      try(silent = TRUE)

    if (inherits(data, "try-error")) {
      tibble(id = i, valid = FALSE, trial_type = "jatos-validation")
    } else {
      data |>
        mutate(id = i, .before = 1) |>
        full_join(
          tibble(id = i, valid = TRUE, trial_type = "jatos-validation"),
          by = c("id", "trial_type")
        )
    }
  })) |>
  select(data_jspsych) |>
  unnest(data_jspsych)


# --- 3. Locate valid and invalid runners --------------------------------------
jatos_valid_run <-
  jspsych_data_all |>
  filter(trial_type == "jatos-validation") |>
  pull(valid)

cli::cli_alert_info(paste0(
  "From a total of {length(jatos_valid_run)} JATOS runners, {.strong ",
  "{sum(jatos_valid_run)}} contains valid jsPsych data and will be processed ",
  "further."
))


# --- 4. Extract meta-data -----------------------------------------------------
meta_data <-
  jspsych_data_all |>
  select(all_of(.meta_cols)) |>
  group_by(id) |>
  fill(everything(), .direction = "downup") |>
  distinct(id, .keep_all = TRUE) |>
  ungroup() |>
  mutate(age = as.numeric(age))


# --- 5. Extract stimulus mappings ---------------------------------------------

# TBA after a bug in catlaslab is solved


# --- 6. Extract response data -------------------------------------------------
raw_response_data <-
  jspsych_data_all |>
  #filter(trial_type == "experiment-trial") |>
  filter(!is.na(stage)) |> # Cannot use the trial_type currently due to a bug in experiment code; to be solved within catlaslab
  select(all_of(.resp_cols)) |>
  mutate(
    cues_raw = cues,
    cues = {
      opts <- names(.cues_map)
      choose <- map_int(cues, \(x) which(map_lgl(.cues_map, \(y) x %in% y)))
      opts[choose]
    },
    cues_reversed = if_else(cues_raw == cues, FALSE, TRUE),
    .after = cues
  ) |>
  select(-cues_raw)


# --- 7. Validate response against meta data -----------------------------------
meta_ids <- unique(meta_data$id)
resp_ids <- unique(raw_response_data$id)

missing_meta <- resp_ids[!resp_ids %in% meta_ids]
missing_resp <- meta_ids[!meta_ids %in% resp_ids]

if (!is_empty(missing_meta)) {
  cli::cli_alert_danger("Some participants have responses but no meta-data recorded.")
  cli::cli_alert_info("Double-check id{?s} {as.character(missing_meta)}")
}

if (!is_empty(missing_resp)) {
  cli::cli_alert_danger("Some participants have meta-data but no responses recorded.")
  cli::cli_alert_info("Double-check id{?s} {as.character(missing_resp)}")
}


